import { CreateProjectInput, CreateTaskInput, CreateUserInput, ListTasksInput, ProjectDto, TaskDto, toTaskDto, UserDto } from './task-dtos';
import { NotFoundError } from '../domain/errors';
import { Project } from '../domain/project';
import { ProjectRepository, TaskFilters, TaskRepository, UserRepository } from '../domain/repositories';
import { Task } from '../domain/task';
import { TaskStatus } from '../domain/task-status';
import { User } from '../domain/user';

export class TaskService {
  public constructor(
    private readonly users: UserRepository,
    private readonly projects: ProjectRepository,
    private readonly tasks: TaskRepository,
  ) {}

  public createUser(input: CreateUserInput): UserDto {
    const user = new User(this.users.nextId(), input.name);
    this.users.save(user);
    return { id: user.id, name: user.name };
  }

  public createProject(input: CreateProjectInput): ProjectDto {
    const project = new Project(this.projects.nextId(), input.name);
    this.projects.save(project);
    return { id: project.id, name: project.name };
  }

  public createTask(projectId: string, input: CreateTaskInput): TaskDto {
    this.requireProject(projectId);
    if (input.assigneeId !== undefined && !this.users.findById(input.assigneeId)) {
      throw new NotFoundError('Assignee');
    }
    const dueDate = input.dueDate === undefined ? undefined : new Date(input.dueDate);
    const task = new Task(
      this.tasks.nextId(), projectId, input.title, input.description, dueDate, input.assigneeId,
      input.status === undefined ? TaskStatus.todo() : TaskStatus.create(input.status),
    );
    this.tasks.save(task);
    return toTaskDto(task);
  }

  public listTasks(projectId: string, input: ListTasksInput): TaskDto[] {
    this.requireProject(projectId);
    const filters: TaskFilters = {
      status: input.status === undefined ? undefined : TaskStatus.create(input.status).value,
      assigneeId: input.assigneeId,
    };
    return this.tasks.findByProjectId(projectId, filters).map(toTaskDto);
  }

  public markTaskDone(taskId: string): TaskDto {
    const task = this.tasks.findById(taskId);
    if (!task) throw new NotFoundError('Task');
    task.markDone();
    this.tasks.save(task);
    return toTaskDto(task);
  }

  private requireProject(projectId: string): void {
    if (!this.projects.findById(projectId)) throw new NotFoundError('Project');
  }
}

